#!/usr/bin/env python3
"""Generate src/dcalc/registry_gen.c from registry/mettadinc_registry.json.

The registry is emitted as s-expression text (parsed once by sx_parse_all at
startup) together with the sha256 digest of the JSON file, so the frontend is
driven by the registry rather than by hand-written tables.  Encoding:
  object -> (Dict (key value) ...)   array -> (List x ...)
  string -> "text"   integer -> the digits   true/false/null -> True/False/Null
Keys "doc" and "note" are prose and are left out.
  --check   exit 1 if the generated file is stale.
"""
import hashlib, json, os, sys
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
REG = os.path.join(ROOT, "registry", "mettadinc_registry.json")
OUT = os.path.join(ROOT, "src", "dcalc", "registry_gen.c")
# Beyond-release registry (hive answer 1 on t-2026-11-12-mettadinc-m4-estimates): the release registry plus the
# local patches; compiled into a separate table selected only by --beyond-release.  registry_gen.c is unchanged.
BREG = os.path.join(ROOT, "registry", "beyond", "mettadinc_registry_beyond.json")
BOUT = os.path.join(ROOT, "src", "dcalc", "registry_beyond_gen.c")
SKIP = {"doc", "note"}


def q(s):
    return '"' + s.replace("\\", "\\\\").replace('"', '\\"') + '"'


def sx(v):
    if isinstance(v, dict):
        return "(Dict" + "".join(" (%s %s)" % (q(k), sx(v[k])) for k in v if k not in SKIP) + ")"
    if isinstance(v, list):
        return "(List" + "".join(" " + sx(x) for x in v) + ")"
    if isinstance(v, bool):
        return "True" if v else "False"
    if v is None:
        return "Null"
    if isinstance(v, int):
        return str(v)
    if isinstance(v, str):
        return q(v)
    raise SystemExit("gen_registry: unsupported JSON value %r" % (v,))


def c_lit(s):
    return '"' + s.replace("\\", "\\\\").replace('"', '\\"') + '"'


def render(reg=REG, src="registry/mettadinc_registry.json", sym="dc_registry"):
    raw = open(reg, "rb").read()
    digest = hashlib.sha256(raw).hexdigest()
    text = sx(json.loads(raw))
    parts = [text[i:i + 2000] for i in range(0, len(text), 2000)]
    out = ["/* GENERATED by tools/gen_registry.py from %s." % src,
           " * Do not edit; rerun the generator. */",
           '#include "registry_gen.h"',
           "",
           'const char %s_digest[] = "%s";' % (sym, digest),
           "const char *const %s_parts[] = {" % sym]
    out += ["    %s," % c_lit(p) for p in parts]
    out += ["    0", "};", ""]
    return "\n".join(out)


def main():
    jobs = [(OUT, render())]
    jobs.append((BOUT, render(BREG if os.path.exists(BREG) else REG,
                              "registry/beyond/mettadinc_registry_beyond.json", "dc_registry_beyond")))
    if "--check" in sys.argv:
        stale = [o for o, new in jobs if (open(o).read() if os.path.exists(o) else "") != new]
        for o in stale:
            print("gen_registry: %s is stale; run tools/gen_registry.py" % os.path.relpath(o, ROOT))
        if stale:
            return 1
        print("gen_registry: up to date")
        return 0
    for o, new in jobs:
        old = open(o).read() if os.path.exists(o) else None
        if old != new:
            open(o, "w").write(new)
            print("gen_registry: wrote %s" % os.path.relpath(o, ROOT))
    return 0


if __name__ == "__main__":
    sys.exit(main())
